{
  "headline": "Meropenem supply traces to Qilu Antibiotics Pharmaceutical Co., Ltd., last inspected VAI 2026-07-16; Corvale Lakeside has 11 days on hand",
  "headline_cites": ["E7", "D3"],
  "sentences": [
    {
      "text": "The product label identifies Qilu Antibiotics Pharmaceutical Co., Ltd. as the manufacturer for meropenem NDC 51810050302.",
      "cites": ["E7"]
    },
    {
      "text": "FDA records show the plant was inspected on 2026-07-16 and classified VAI, with the classification known on 2026-10-05.",
      "cites": ["E6"]
    },
    {
      "text": "Earlier FDA inspections of the same facility in 2015-09-22 and 2023-05-30 were also classified VAI.",
      "cites": ["E4", "E5"]
    },
    {
      "text": "Corvale Lakeside holds 29 units at 2.6 units per day, providing 11 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 337 units at 15.1 units per day for 22 days on hand, and Corvale General holds 425 units at 15.2 units per day for 28 days on hand.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The recommended option is to buy from Gland Pharma Limited, which is not on FDA's shortage list today and whose plant was last inspected VAI 2023-06-27.",
      "cites": []
    }
  ]
}
